Z \ar[rd] & & X \ar[ld] \\
T \ar[rr] & & S
}
$$
commutes. In this situation we can define a functor
\begin{equation}
\mathit{Mor}_S(Z, X) : (\Sch/S)^{opp} \longrightarrow \textit{Sets},
\quad
T \longmapsto \{b\text{ as above}\}
\end{equation}
